//! The editor's "Atollo Dark" and "Atollo Light": VSCodium's Dark Modern
//! and Light Modern with the brand colors, as the extension `atollo.theme`
//! (`tauri/editor-theme`, generated by docs/brand/themes.py).
//!
//! Embedded in the exe and installed with the server's own command line
//! before the server starts, whenever the installed version is not the
//! embedded one: the windows open with the theme already there. The kit owns
//! it, like the files of setup/kit_files.rs: uninstalled, it comes back.

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::Stdio;

use anyhow::{bail, Context, Result};

use crate::env::KitEnv;
use crate::kit::Kit;

pub const ID: &str = "atollo.theme";
pub const DARK: &str = "Atollo Dark";
pub const LIGHT: &str = "Atollo Light";

const FILES: &[(&str, &str)] = &[
    (
        "package.json",
        include_str!("../../editor-theme/package.json"),
    ),
    (
        "themes/dark.json",
        include_str!("../../editor-theme/themes/dark.json"),
    ),
    (
        "themes/light.json",
        include_str!("../../editor-theme/themes/light.json"),
    ),
];

/// The embedded extension's version.
fn version() -> String {
    serde_json::from_str::<serde_json::Value>(FILES[0].1)
        .ok()
        .and_then(|p| p["version"].as_str().map(str::to_owned))
        .unwrap_or_default()
}

/// The embedded version is in the server's extensions folder
/// (`<id>-<version>`, a local package has no platform suffix).
fn is_current(kit: &Kit) -> bool {
    let dir = crate::editor::ext::extensions_dir(kit).join(format!("{ID}-{}", version()));
    dir.join("package.json").is_file()
}

/// The extension as a `.vsix`: the files under `extension/`, which is all
/// the server reads from a local package.
fn write_vsix(path: &Path) -> Result<()> {
    let file = fs::File::create(path).with_context(|| path.display().to_string())?;
    let mut zip = zip::ZipWriter::new(file);
    let options = zip::write::SimpleFileOptions::default();
    for (name, content) in FILES {
        // The checkout may have turned LF into CRLF: same JSON either way.
        zip.start_file(format!("extension/{name}"), options)?;
        zip.write_all(content.as_bytes())?;
    }
    zip.finish()?;
    Ok(())
}

/// Installs the theme when the server does not have this version. Called
/// before the server starts; a failure leaves the editor on VSCodium's
/// themes and is retried at the next start.
pub fn ensure(kit: &Kit, env: &KitEnv) -> Result<()> {
    if is_current(kit) {
        return Ok(());
    }
    let work: PathBuf = kit.data().join(r"tmp\setup\theme");
    let _ = fs::remove_dir_all(&work);
    fs::create_dir_all(&work)?;
    let vsix = work.join("atollo-theme.vsix");
    write_vsix(&vsix)?;
    let job = crate::jobs::Job::new()?;
    let mut cmd = crate::editor::ext::server_cli(kit, env);
    // --force: also over a newer or equal version left by another build.
    cmd.arg("--install-extension")
        .arg(&vsix)
        .arg("--force")
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let child = crate::jobs::spawn_in(&mut cmd, &job).context("server --install-extension")?;
    let out = child
        .wait_with_output()
        .context("server --install-extension")?;
    let _ = fs::remove_dir_all(&work);
    if !is_current(kit) {
        bail!(
            "{ID} {} not installed: {}{}",
            version(),
            String::from_utf8_lossy(&out.stdout).trim(),
            String::from_utf8_lossy(&out.stderr).trim()
        );
    }
    crate::log::info(&format!("editor theme {} installed", version()));
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::kit::{tests::TempDir, Arch};
    use serde_json::Value;

    #[test]
    fn embedded_extension_is_valid() {
        let package: Value = serde_json::from_str(FILES[0].1).unwrap();
        assert_eq!(
            format!(
                "{}.{}",
                package["publisher"].as_str().unwrap(),
                package["name"].as_str().unwrap()
            ),
            ID
        );
        assert!(version().starts_with("1.0."));
        let themes = package["contributes"]["themes"].as_array().unwrap();
        for (theme, label, kind) in [(&themes[0], DARK, "dark"), (&themes[1], LIGHT, "light")] {
            assert_eq!(theme["id"], label);
            let rel = theme["path"].as_str().unwrap().trim_start_matches("./");
            let (_, text) = FILES.iter().find(|(n, _)| *n == rel).unwrap();
            let colors: Value = serde_json::from_str(text).unwrap();
            assert_eq!(colors["type"], kind);
            assert!(colors["tokenColors"].as_array().unwrap().len() > 50);
            assert!(colors["colors"]["editor.background"].is_string());
        }
    }

    #[test]
    fn vsix_holds_the_extension() {
        let tmp = TempDir::new("theme-vsix");
        let kit = Kit::at(tmp.0.clone(), Arch::X64);
        let path = tmp.0.join("t.vsix");
        write_vsix(&path).unwrap();
        let mut zip = zip::ZipArchive::new(fs::File::open(&path).unwrap()).unwrap();
        assert!(zip.by_name("extension/package.json").is_ok());
        assert!(zip.by_name("extension/themes/dark.json").is_ok());
        assert!(!is_current(&kit));
        let dir = crate::editor::ext::extensions_dir(&kit).join(format!("{ID}-{}", version()));
        fs::create_dir_all(&dir).unwrap();
        fs::write(dir.join("package.json"), FILES[0].1).unwrap();
        assert!(is_current(&kit));
    }
}
